  values ('947ba320-5051-4c1d-9a39-4df3a5459f44', 'a8777d77-07c3-453a-b2e2-06d91f4a8426', 'ec3c5f13-b366-4eb8-ada5-66577495b2e0', '41cbd944-6d16-476c-9763-8c1245a172c4', 'bb4aa2c5-50d5-469d-8296-1ad0b9d82dc5', '0dcfe24f-6774-4a8f-ac55-93d302c9ce30', '6888e404-feb4-4fad-8648-07c8233e8a02', 2, '2026-07-01 20:00:00 America/New_York'::timestamptz, 'confirmed', 'import', 'bb4aa2c5-50d5-469d-8296-1ad0b9d82dc5', 2, 1, 30, 26, '2026-07-01 20:00:00 America/New_York'::timestamptz + interval '70 minutes', '2026-07-01 20:00:00 America/New_York'::timestamptz + interval '75 minutes');
  select m.id, p.id, (array['🔥','😂','👀','💀','🏆'])[1 + floor(random() * 5)::int]
  from (select id from public.messages where not is_bot order by created_at desc limit 25) m
  cross join lateral (select id from public.players where email is not null order by random() limit 2) p
  on conflict do nothing;
  select e.id, p.id, (array['going','going','going','maybe','no'])[1 + floor(random() * 5)::int]
  from public.events e cross join lateral (select id from public.players where email is not null order by random() limit 18) p
  where e.kind <> 'deadline' on conflict do nothing;
  select '6a510342-e7db-4e4e-8fa1-790c8154f481', p.id, 4000, random() < 0.8, case when random() < 0.8 then pg_temp.ts(1, 1, '19:00') + (random() * interval '20 days') end
  from public.players p where p.id in (select player_id from public.team_memberships tm join public.teams t on t.id = tm.team_id where t.season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481') on conflict do nothing;
update public.players p set user_id = u.id from auth.users u where p.email = u.email::extensions.citext and p.user_id is null;

do $$
declare rec record; grec record; fmt jsonb;
begin
  -- Week 5 matches that have not started: wipe simulated results.
  for rec in select id from public.matches where season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481' and status = 'scheduled' and week_id = '86bbd3ce-09e7-40a9-9f26-ba1f7c875dd9' loop
    delete from public.frames where game_id in (select id from public.games where match_id = rec.id);
    delete from public.games where match_id = rec.id;
    update public.matches set winner_team_id = null, home_games = 0, away_games = 0, home_points = 0, away_points = 0, submitted_by = null, submitted_at = null, submitting_team_id = null, confirmed_by = null, confirmed_at = null, current_game = 1, entry_mode = null where id = rec.id;
    delete from public.confirmations where match_id = rec.id;
  end loop;
  -- Live matches (happening now): keep game 1 and the first four frames of game 2.
  select format into fmt from public.seasons where id = '6a510342-e7db-4e4e-8fa1-790c8154f481';
  for rec in select * from public.matches where season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481' and status = 'live' loop
    delete from public.frames where game_id in (select id from public.games where match_id = rec.id and number >= 3);
    delete from public.games where match_id = rec.id and number >= 3;
    select * into grec from public.games where match_id = rec.id and number = 2;
    if grec.id is not null then
      delete from public.frames where game_id = grec.id and number > 4;
      update public.games set status = 'live', ended_at = null, winner_team_id = null,
        home_score = (select coalesce(sum(points),0) from public.frames f where f.game_id = grec.id and f.scoring_team_id = rec.home_team_id),
        away_score = (select coalesce(sum(points),0) from public.frames f where f.game_id = grec.id and f.scoring_team_id = rec.away_team_id),
        frame_count = (select count(*) from public.frames f where f.game_id = grec.id)
      where id = grec.id;
    end if;
    update public.matches set winner_team_id = null, submitted_by = null, submitted_at = null, submitting_team_id = null, confirmed_by = null, confirmed_at = null, current_game = 2,
      home_games = (select count(*) from public.games where match_id = rec.id and status = 'final' and winner_team_id = rec.home_team_id),
      away_games = (select count(*) from public.games where match_id = rec.id and status = 'final' and winner_team_id = rec.away_team_id),
      home_points = (select coalesce(sum(home_score),0) from public.games where match_id = rec.id),
      away_points = (select coalesce(sum(away_score),0) from public.games where match_id = rec.id)
    where id = rec.id;
    delete from public.confirmations where match_id = rec.id;
    delete from public.messages where channel_id = (select id from public.channels where match_id = rec.id) and is_bot;
  end loop;
  -- One result still waiting for the opposing captain: the most recent confirmed match.
  update public.matches set status = 'submitted', confirmed_by = null, confirmed_at = null, auto_confirm_at = now() + interval '10 hours', submitted_at = now() - interval '2 hours'
    where id = (select id from public.matches where season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481' and status = 'confirmed' order by scheduled_at desc limit 1);
  delete from public.confirmations where match_id in (select id from public.matches where status = 'submitted');
  -- One open dispute on a week-4 match.
  update public.matches set status = 'disputed', confirmed_by = null, confirmed_at = null, auto_confirm_at = null
    where id = (select id from public.matches where season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481' and status = 'confirmed' and week_id = 'fa8a9ce5-0ce5-4270-a09d-2de055bcd8fa' and entry_mode = 'quick' order by scheduled_at desc limit 1);
    select id, case when submitting_team_id = home_team_id then (select player_id from public.team_memberships where team_id = away_team_id and role = 'captain' limit 1) else (select player_id from public.team_memberships where team_id = home_team_id and role = 'captain' limit 1) end,
      case when submitting_team_id = home_team_id then away_team_id else home_team_id end,
      'Game 2 was 15–13, not 15–9. We have the board photo.', scheduled_at + interval '3 hours'
    from public.matches where status = 'disputed';
  delete from public.confirmations where match_id in (select id from public.matches where status = 'disputed');
  -- One open sub request for the next upcoming match.
    select m.home_team_id, m.id, m.night_id, m.scheduled_at, 'Need one sub — our captain is at a wedding. Doubles, just show up and slide.',
      (select player_id from public.team_memberships where team_id = m.home_team_id and role = 'captain' limit 1), now() - interval '1 day'
    from public.matches m where m.season_id = '6a510342-e7db-4e4e-8fa1-790c8154f481' and m.status = 'scheduled' and m.scheduled_at > now() order by m.scheduled_at limit 1;
  -- Inbox items for the commissioner and the pending-match captain.
    select '73142fc6-8e72-471f-be28-0cef8391818f', 'dispute', 'New dispute filed', 'A captain disputed a Week 4 result. Review it in the admin queue.', '/admin/results?tab=disputes', now() - interval '2 hours';
    select tm.player_id, 'score_confirm_request', 'Confirm your result', 'The other captain submitted the score. Confirm or dispute it.', '/matches/' || m.id::text || '/confirm', now() - interval '110 minutes'
    from public.matches m join public.team_memberships tm on tm.team_id = case when m.submitting_team_id = m.home_team_id then m.away_team_id else m.home_team_id end and tm.role = 'captain'
    where m.status = 'submitted';
end $$;

-- sanity: 60 S26 matches imported; 152 players; 111 accounts
