insert into public.rules_pages (slug, title, body_md, sort_order) values ('rules', 'Rules & Policies', '# Table Shuffleboard Rules
insert into public.faq_items (question, answer_md, sort_order) values
  ('How do I install the app?', 'On iPhone, open the site in Safari, tap **Share**, then **Add to Home Screen**. On Android, tap **Install** when the banner appears or use the browser menu. See the Install page for pictures.', 0),
  ('Do I need an account to see standings?', 'No. Schedule, standings, results, events and rules are public. Sign in only to keep score, chat and get notifications.', 1),
  ('How do I join my team?', 'Ask your captain for the 6-character join code, or pick your name from the roster the commissioner imported.', 2),
  ('I entered the wrong score. What now?', 'If the match has not been confirmed yet, the opposing captain can dispute it and the commissioner will fix it. If it is already confirmed, message the commissioner from the Rules page.', 3),
  ('Why can''t I get push notifications on my iPhone?', 'iPhones only allow web push for apps that are added to the Home Screen (iOS 16.4 or newer). Install the app first, then turn notifications on in Settings.', 4),
  ('What counts as a hanger?', 'A weight that hangs over the far end of the board. It scores 4 points. Line calls go to the lower zone.', 5),
  ('What are the playoffs?', 'After the 10-week double round robin, the top four teams on each night play 1 v 4 and 2 v 3, then a final. The five night champions can meet in the Champion of Champions night.', 6),
  ('How are ties broken in the standings?', 'Match win %, then head-to-head, then game differential, then point differential, then a commissioner decision. Tap a rank in the standings to see which rule applied.', 7);
