insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Fall Playoffs begin', 'playoffs', pg_temp.ts(11, 1, '18:00'), 'Conshohocken Bocce Club', 'Top four on each night. 1 v 4 and 2 v 3, same scoring rules, same bar.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Halloween Shuffle Social', 'social', pg_temp.ts(3, 6, '19:00'), 'Conshohocken Bocce Club', 'Costumes encouraged, hangers mandatory. Open boards all night, prizes for best team costume.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Saturday Doubles Tournament', 'tournament', pg_temp.ts(6, 6, '13:00'), 'Conshohocken Bocce Club', 'Blind-draw doubles. $10 per player, winner takes the pot and eternal glory. Sign up by Thursday.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Champion of Champions Night', 'playoffs', pg_temp.ts(13, 5, '18:00'), 'Conshohocken Bocce Club', 'The five night champions settle it. Everyone is welcome to watch.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'End of Season Banquet', 'banquet', pg_temp.ts(14, 6, '18:30'), 'Conshohocken Bocce Club, upstairs hall', 'Awards, dinner, trophies and the Hanger of the Season. Plus-ones welcome.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
insert into public.events (season_id, title, kind, starts_at, location, description, created_by, target_night_ids) values ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Dues deadline', 'deadline', pg_temp.ts(1, 5, '23:00'), null, 'Last day to pay Fall dues ($40). Unpaid players are ineligible for playoffs.', '73142fc6-8e72-471f-be28-0cef8391818f', '{}');
