insert into public.announcements (season_id, title, body, pinned, push, published_at, created_by) values
  ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Welcome to Fall 2026 🎉', 'Thirty teams, five nights, one bar. Scores go in the app now — no more QR form. Captains: share your join code with your team. Dues are $40, see Dana.', true, true, pg_temp.ts(1, 1, '12:00'), '73142fc6-8e72-471f-be28-0cef8391818f'),
  ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Parking note for Friday', 'The side lot is closed Friday for the street fair. Use the Elm Street lot; it is a two minute walk.', false, true, pg_temp.ts(3, 4, '15:00'), '73142fc6-8e72-471f-be28-0cef8391818f'),
  ('6a510342-e7db-4e4e-8fa1-790c8154f481', 'Dues reminder', 'Half the league has paid — thank you! Everyone else: dues are due this Friday. Unpaid players are not playoff eligible.', false, false, pg_temp.ts(4, 2, '10:00'), '73142fc6-8e72-471f-be28-0cef8391818f');
